import React, { useState, useEffect, useCallback, useRef } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Dashboard from './pages/Dashboard';
import CustomerListPage from './pages/CustomerListPage';
import AddCustomerPage from './pages/AddCustomerPage';
import CustomerDetailPage from './pages/CustomerDetailPage';
import AdminPage from './pages/AdminPage';
import DeliveryPage from './pages/DeliveryPage';
import PasswordModal from './components/PasswordModal';
import { useDarkMode } from './hooks/useDarkMode';
import { checkAdminPassword } from './services/api';
import { LanguageProvider, useLanguage } from './contexts/LanguageContext';

export type Route =
  | { name: 'dashboard' }
  | { name: 'customers' }
  | { name: 'add-customer' }
  | { name: 'deliveries' }
  | { name: 'admin' }
  | { name: 'customer-detail'; id: string }
  | { name: 'not-found' };

const parseRoute = (hash: string): Route => {
    const path = hash.substring(1) || '/';
    const parts = path.split('/').filter(Boolean);

    if (parts.length === 0 || path === '/') return { name: 'dashboard' };

    switch (parts[0]) {
        case 'customers':
            return parts[1] ? { name: 'customer-detail', id: parts[1] } : { name: 'customers' };
        case 'add-customer':
            return { name: 'add-customer' };
        case 'deliveries':
            return { name: 'deliveries' };
        case 'admin':
            return { name: 'admin' };
        default:
            return { name: 'not-found' };
    }
};

const routeToPath = (route: Route): string => {
    switch (route.name) {
        case 'dashboard': return '#/';
        case 'customers': return '#/customers';
        case 'add-customer': return '#/add-customer';
        case 'deliveries': return '#/deliveries';
        case 'admin': return '#/admin';
        case 'customer-detail': return `#/customers/${route.id}`;
        default: return '#/';
    }
};

const AppContent: React.FC = () => {
    useDarkMode();
    const { t } = useLanguage();

    const [route, setRoute] = useState(() => parseRoute(window.location.hash));
    const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
    const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    const lastGoodRoute = useRef(route);

    useEffect(() => {
        if (route.name !== 'admin' && route.name !== 'not-found') {
            lastGoodRoute.current = route;
        }
        // Auto-close sidebar on route change for mobile
        setIsSidebarOpen(false);
    }, [route]);

    useEffect(() => {
        const handleHashChange = () => {
            const newRoute = parseRoute(window.location.hash);

            if (newRoute.name === 'admin' && !isAdminAuthenticated) {
                setIsPasswordModalOpen(true);
                // Don't update the route state yet, just show the modal.
                // The UI will stay on the previous page while the URL shows '/admin'.
            } else {
                setIsPasswordModalOpen(false); // Close modal if navigating away or already authed
                setRoute(newRoute);
            }
        };

        window.addEventListener('hashchange', handleHashChange);
        handleHashChange(); // Check route on initial load
        return () => window.removeEventListener('hashchange', handleHashChange);
    }, [isAdminAuthenticated]); // Re-subscribe if the authentication state changes.

    const handlePasswordModalClose = () => {
        setIsPasswordModalOpen(false);
        // If the user closes the modal, revert the URL to the last non-admin page.
        // This will trigger the hashchange listener again, which will correctly set the route state.
        if (window.location.hash !== routeToPath(lastGoodRoute.current)) {
            window.location.hash = routeToPath(lastGoodRoute.current);
        }
    };

    const handlePasswordSubmit = async (password: string) => {
        const success = await checkAdminPassword(password);
        if (success) {
            setIsAdminAuthenticated(true);
            setIsPasswordModalOpen(false);
            // After successful auth, if the user is still trying to access admin,
            // explicitly set the route to admin. The listener's dependency on
            // `isAdminAuthenticated` will handle future navigations correctly.
            if (parseRoute(window.location.hash).name === 'admin') {
                setRoute({ name: 'admin' });
            }
        } else {
            alert(t('app.incorrectPassword'));
        }
    };

    const renderContent = () => {
        switch (route.name) {
            case 'dashboard':
                return <Dashboard />;
            case 'customers':
                return <CustomerListPage />;
            case 'add-customer':
                return <AddCustomerPage />;
            case 'deliveries':
                return <DeliveryPage />;
            case 'admin':
                // Only render AdminPage if authenticated. If not, this logic
                // will have already shown the modal, and the route state won't be 'admin'.
                return isAdminAuthenticated ? <AdminPage /> : null;
            case 'customer-detail':
                return <CustomerDetailPage id={route.id} />;
            case 'not-found':
            default:
                return <div className="text-center p-8">{t('app.pageNotFound')}</div>;
        }
    };

    return (
        <>
            <div className="flex h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 overflow-hidden relative">
                <Sidebar 
                    currentRoute={route} 
                    isOpen={isSidebarOpen} 
                    onClose={() => setIsSidebarOpen(false)} 
                />
                <div className="flex-1 flex flex-col overflow-hidden">
                    <Header onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} />
                    <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 dark:bg-gray-800 p-4 sm:p-6 lg:p-8">
                        {renderContent()}
                    </main>
                </div>
                <PasswordModal 
                    isOpen={isPasswordModalOpen}
                    onClose={handlePasswordModalClose}
                    onSubmit={handlePasswordSubmit}
                />
            </div>
        </>
    );
};

const App: React.FC = () => (
    <LanguageProvider>
        <AppContent />
    </LanguageProvider>
);

export default App;

